def xp_needed(level):
    if level <= 5:
        return level * 100
    if level <= 10:
        return level * 150
    return level * 200
def message(xp, level):
    needed = xp_needed(level)
    if xp >= needed:
        return f'Level {level + 1}!'
    return f'Need {needed - xp}'
