def needed(level):
    return level * 100
def levels_gained(xp, level):
    gained = 0
    while xp >= needed(level):
        xp -= needed(level)
        level += 1
        gained += 1
    return gained
print(levels_gained(650, 2))

def base(weight):
    if weight <= 5:
        return 10
    return 20
def discount(total, member):
    if member and total >= 20:
        return total * 0.9
    return total
